    edges.append((v[0], v[2]))
    edges.append((v[1], v[2]))
for g in range(5):
    for i in range(3):
        edges.append((3*g+i, 3*g+3+i))

n_vertices = 18
n_edges = 33
max_label = 33

# Build edge index for quick lookup
edge_set = set()
for u, v in edges:
    edge_set.add((min(u,v), max(u,v)))

adj = [[] for _ in range(n_vertices)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

def verify(labels):
    if len(set(labels)) != n_vertices:
        return False
    diffs = set()
    for u, v in edges:
        d = abs(labels[u] - labels[v])
        if d == 0 or d in diffs:
            return False
        diffs.add(d)
    return len(diffs) == n_edges

# Backtracking with forward checking
def solve_backtrack():
    labels = [-1] * n_vertices
    used_labels = set()
    used_diffs = set()

    # Order vertices by degree (highest first)
    order = sorted(range(n_vertices), key=lambda x: -len(adj[x]))

    def backtrack(idx):
        if idx == n_vertices:
            return True

        v = order[idx]

        for label in range(max_label + 1):
            if label in used_labels:
                continue

            # Check if this label creates any duplicate diffs
            new_diffs = []
            valid = True
            for u in adj[v]:
                if labels[u] != -1:
                    d = abs(label - labels[u])
                    if d == 0 or d in used_diffs or d in new_diffs:
                        valid = False
                        break
                    new_diffs.append(d)

            if valid:
                labels[v] = label
                used_labels.add(label)
                for d in new_diffs:
                    used_diffs.add(d)

                if backtrack(idx + 1):
                    return True

                labels[v] = -1
                used_labels.remove(label)
                for d in new_diffs:
                    used_diffs.remove(d)

        return False

    if backtrack(0):
        result = [-1] * n_vertices
        for i, v in enumerate(order):
            result[v] = labels[v]
        return result
    return None

start = time.time()
result = solve_backtrack()
elapsed = time.time() - start
